(function () {
  function showMsg(text, isErr) {
    var el = document.getElementById("mtMsg");
    if (!el) return;
    el.hidden = false;
    el.textContent = text;
    el.classList.toggle("err", !!isErr);
    if (!isErr) {
      setTimeout(function () {
        el.hidden = true;
      }, 2200);
    }
  }

  function setStatus(name, status, checkbox) {
    if (!window.frappe || !frappe.call) {
      showMsg("Could not reach ERP. Refresh and try again.", true);
      if (checkbox) checkbox.checked = status !== "Closed";
      return;
    }
    checkbox.disabled = true;
    frappe.call({
      method: "frappe.client.set_value",
      args: {
        doctype: "ToDo",
        name: name,
        fieldname: "status",
        value: status
      },
      callback: function (r) {
        checkbox.disabled = false;
        if (r && r.exc) {
          showMsg("Could not update task.", true);
          checkbox.checked = status !== "Closed";
          return;
        }
        // Move row between lists without full reload
        var item = checkbox.closest(".mt-item");
        if (!item) {
          window.location.reload();
          return;
        }
        if (status === "Closed") {
          item.classList.add("is-done");
          checkbox.classList.remove("mt-complete");
          checkbox.classList.add("mt-reopen");
          var done = document.getElementById("mtDone");
          var emptyDone = document.getElementById("mtEmptyDone");
          if (emptyDone) emptyDone.remove();
          if (done) done.prepend(item);
          showMsg("Marked complete");
        } else {
          item.classList.remove("is-done");
          checkbox.classList.remove("mt-reopen");
          checkbox.classList.add("mt-complete");
          var open = document.getElementById("mtOpen");
          var emptyOpen = document.getElementById("mtEmptyOpen");
          if (emptyOpen) emptyOpen.remove();
          if (open) open.prepend(item);
          else window.location.reload();
          showMsg("Reopened");
        }
        var openCount = document.querySelectorAll("#mtOpen .mt-item, #mtOverdue .mt-item").length;
        var badge = document.getElementById("mtCountOpen");
        if (badge) badge.textContent = openCount + " open";
      },
      error: function () {
        checkbox.disabled = false;
        checkbox.checked = status !== "Closed";
        showMsg("Could not update task.", true);
      }
    });
  }

  document.addEventListener("DOMContentLoaded", function () {
    if (!document.querySelector(".mt-page")) return;
    document.querySelectorAll(".mt-complete").forEach(function (cb) {
      cb.addEventListener("change", function () {
        if (!cb.checked) return;
        setStatus(cb.getAttribute("data-name"), "Closed", cb);
      });
    });
    document.querySelectorAll(".mt-reopen").forEach(function (cb) {
      cb.addEventListener("change", function () {
        if (cb.checked) return;
        setStatus(cb.getAttribute("data-name"), "Open", cb);
      });
    });
  });
})();

css:
/* Desk-like My Tasks — align with manage-shifts */
.page-content-wrapper .main-column,
.web-page-content,
.page_content {
  max-width: 100% !important;
  width: 100% !important;
  padding-left: 12px !important;
  padding-right: 12px !important;
}
.navbar .container,
.web-footer .container,
header .container {
  max-width: none;
}

.mt-page {
  font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 13px;
  color: #36414c;
  line-height: 1.45;
  padding: 8px 0 40px;
  max-width: 720px;
  margin: 0 auto;
  box-sizing: border-box;
}

.mt-gate {
  max-width: 420px;
  margin: 40px auto;
  text-align: center;
  font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}
.mt-gate h2 { color: #2c3338; font-size: 18px; font-weight: 600; }
.mt-gate p { color: #6c7680; }

.mt-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  margin: 0 0 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid #d1d8dd;
}
.mt-toolbar h2 {
  margin: 0;
  font-size: 18px;
  font-weight: 600;
  color: #2c3338;
}
.mt-nav {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.mt-nav-range {
  font-weight: 600;
  color: #2c3338;
  font-size: 13px;
}
.mt-toolbar-actions {
  display: flex;
  gap: 10px;
  align-items: center;
}
.mt-count {
  font-size: 12px;
  font-weight: 600;
  color: #2490ef;
  background: #eaf4fe;
  border-radius: 999px;
  padding: 4px 10px;
}
.mt-count.muted {
  color: #6c7680;
  background: #eef0f2;
}

.mt-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: #fff;
  color: #2490ef;
  border: 1px solid #2490ef;
  border-radius: 6px;
  padding: 6px 12px;
  cursor: pointer;
  font-size: 13px;
  font-weight: 500;
  text-decoration: none;
  line-height: 1.2;
}
.mt-btn:hover { background: #f0f8ff; color: #1a7fd1; text-decoration: none; }
.mt-btn.primary { background: #2490ef; color: #fff; }
.mt-btn.primary:hover { background: #1a7fd1; }
.mt-btn.secondary { color: #36414c; border-color: #d1d8dd; }
.mt-btn.secondary:hover { border-color: #2490ef; color: #2490ef; }

.mt-section { margin: 0 0 22px; }
.mt-section-title {
  margin: 0 0 10px;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: #6c7680;
}
.mt-section-title.overdue { color: #e24c4c; }

.mt-list {
  list-style: none;
  margin: 0;
  padding: 0;
  border: 1px solid #d1d8dd;
  border-radius: 8px;
  background: #fff;
  overflow: hidden;
}
.mt-item {
  border-bottom: 1px solid #eef0f2;
  margin: 0;
}
.mt-item:last-child { border-bottom: none; }
.mt-check-wrap {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  padding: 12px 14px;
  margin: 0;
  cursor: pointer;
  font-weight: 400;
}
.mt-check-wrap:hover { background: #f8fafb; }
.mt-check-wrap input[type="checkbox"] {
  margin-top: 3px;
  width: 18px;
  height: 18px;
  accent-color: #2490ef;
  flex: 0 0 auto;
}
.mt-body { flex: 1; min-width: 0; }
.mt-desc {
  display: block;
  color: #2c3338;
  font-size: 14px;
  font-weight: 500;
  white-space: pre-wrap;
  word-break: break-word;
}
.mt-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 6px;
  align-items: center;
}
.mt-badge {
  font-size: 11px;
  font-weight: 600;
  border-radius: 999px;
  padding: 2px 8px;
  background: #eef0f2;
  color: #6c7680;
}
.mt-badge.prio-high { background: #fde8e8; color: #e24c4c; }
.mt-badge.prio-medium { background: #fff4e5; color: #c05600; }
.mt-badge.prio-low { background: #eef0f2; color: #6c7680; }
.mt-date { font-size: 12px; color: #6c7680; }

.mt-item.is-done .mt-desc {
  color: #98a1a9;
  text-decoration: line-through;
}
.mt-item.is-done .mt-check-wrap:hover { background: #f4f5f6; }

.mt-empty {
  margin: 0;
  padding: 16px;
  border: 1px dashed #d1d8dd;
  border-radius: 8px;
  color: #6c7680;
  background: #fafbfc;
}

.mt-msg {
  position: fixed;
  left: 50%;
  bottom: 20px;
  transform: translateX(-50%);
  background: #2c3338;
  color: #fff;
  padding: 10px 16px;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 500;
  z-index: 1300;
  box-shadow: 0 8px 24px rgba(0,0,0,0.25);
}
.mt-msg.err { background: #e24c4c; }
